/* Build Dynamic System Prompt From Form Fields + Current Count */

const schemaResp = $input.first().json;
const data       = schemaResp.Data;
const countResp  = $('Count Participants').first().json;
const current    = countResp?.Data?.Counts?.Total ?? 0;
const chatInput  = $('When chat message received').first().json.chatInput;
const sessionId  = $('When chat message received').first().json.sessionId;

if (!data || !data.FormFields) {
	throw new Error('Form fields not available — check the sweepstakesToken');
}

/* Slug Helper: 'First Name' → 'First_Name' */
const toSlug = (n) => n.trim().replace(/\s+/g, '_');

/* Build Required/Optional Lists */
const required = data.FormFields.filter(f => f.Required);
const optional = data.FormFields.filter(f => !f.Required);
const describe = (f) => {
	const ex   = f.Placeholder ? ` — example: ${f.Placeholder}` : '';
	const opts = (f.Options && f.Options.length) ? ` — pick one: ${f.Options.map(o => `${o.Id}=${o.Name}`).join(', ')}` : '';
	return `- ${f.Name}${ex}${opts}`;
};

/* Build JSON Example Skeleton */
const skeleton = {};
data.FormFields.forEach(f => {
	const slug = toSlug(f.Name);
	if (f.Type === 'email')             skeleton[slug] = 'user@example.com';
	else if (f.Type === 'usphonenumber') skeleton[slug] = '5551234567';
	else if (f.Type === 'birthdate')     skeleton[slug] = 'MM/DD/YYYY';
	else if (f.Type === 'number')        skeleton[slug] = '0';
	else if (f.Type === 'list' && f.Options?.length) skeleton[slug] = String(f.Options[0].Id);
	else                                  skeleton[slug] = '<value>';
});

/* Identify Key Fields For Mapping */
const emailField = data.FormFields.find(f => f.Type === 'email');
const phoneField = data.FormFields.find(f => f.Type === 'usphonenumber');

/* Compose System Message */
const systemPrompt = `You are a friendly sweepstake registration assistant.

The sweepstake currently has ${current} participants. Tell the user they'll be #${current + 1} once registered.

Collect this data ONE field at a time:

Required:
${required.map(describe).join('\n')}
${optional.length ? `\nOptional:\n${optional.map(describe).join('\n')}` : ''}

When you have all required fields, respond with EXACTLY this JSON (no markdown, no extra text):

${JSON.stringify({ action: 'create_participant', ...skeleton }, null, 2)}

Rules:
- Use the field names exactly as shown (underscores).
- For list fields, pass the option ID number.
- Validate emails and phones (10 digits) before sending the final JSON.
- Be warm, brief, and friendly.`;

return {
	json: {
		systemPrompt,
		chatInput,
		sessionId,
		emailFieldSlug: emailField ? toSlug(emailField.Name) : 'Email',
		phoneFieldSlug: phoneField ? toSlug(phoneField.Name) : 'Mobile_Number',
		currentParticipantCount: current
	}
};

/* Transform AI Output JSON Into participant:create Input Shape */

const aiOutput   = $input.first().json.output;
const promptData = $('Build Dynamic Prompt').first().json;

/* LLMs Sometimes Add Narrative Around The JSON; Strip Markdown Fences */
/* And Extract The Outermost {...} Block From Whatever The Model Wrote  */
let raw = String(aiOutput).replace(/```json/g, '').replace(/```/g, '');
const firstBrace = raw.indexOf('{');
const lastBrace  = raw.lastIndexOf('}');

if (firstBrace === -1 || lastBrace === -1 || lastBrace < firstBrace) {
	throw new Error('AI output did not contain a JSON object: ' + raw.slice(0, 200));
}

const clean  = raw.slice(firstBrace, lastBrace + 1).trim();
const parsed = JSON.parse(clean);

if (parsed.action !== 'create_participant') {
	return { json: {} };
}

const { action, ...fields } = parsed;

return {
	json: {
		KeyEmail       : fields[promptData.emailFieldSlug] || '',
		KeyPhoneNumber : fields[promptData.phoneFieldSlug] || '',
		BonusEntries   : 0,
		Fields         : fields
	}
};

